#include <vector>

class Solution {
public:
    int maxKToSort(std::vector<int>& nums) {
        int mask = -1;
        bool found = false;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] != i) {
                if (!found) {
                    mask = nums[i];
                    found = true;
                } else {
                    mask &= nums[i];
                }
            }
        }
        return found ? mask : 0;
    }
};

class Solution {
    public int maxKToSort(int[] nums) {
        int mask = -1;
        boolean found = false;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != i) {
                if (!found) {
                    mask = nums[i];
                    found = true;
                } else {
                    mask &= nums[i];
                }
            }
        }
        return found ? mask : 0;
    }
}

var maxKToSort = function(nums) {
    let mask = -1;
    let found = false;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] !== i) {
            if (!found) {
                mask = nums[i];
                found = true;
            } else {
                mask &= nums[i];
            }
        }
    }
    return found ? mask : 0;
};
